MOD = 10**9 + 7

def count_ways(n):
    # Initialize the dp array
    dp = [[[0 for _ in range(4)] for _ in range(4)] for _ in range(n + 1)]

    # Base case: There's one way to distribute coins to zero gnomes
    dp[0][0][0] = 1

    # Fill the dp table
    for i in range(1, n + 1):
        for j in range(4):
            for k in range(4):
                for l in range(4):
                    if (j + k + l) % 3 != 0:
                        dp[i][k][l] = (dp[i][k][l] + dp[i-1][j][k]) % MOD

    # Sum up all valid ways to distribute coins to n groups of three gnomes
    result = 0
    for j in range(4):
        for k in range(4):
            result = (result + dp[n][j][k]) % MOD

    return result

# Read input
import sys
input = sys.stdin.read
data = input().split()
n = int(data[0])

# Print the result
print(count_ways(n))
